import React, { useState } from "react";
import styled from "styled-components";

import fetchQuery from "../components/fetchQuery";
import PageWrapper from "../components/PageWrapper";
import BookCard from "../components/BookCard";
import CardButton from "../components/CardButton";
import BookGrid from "../components/BookGrid";

const Container = styled.div`
  margin: 20px;
  font-family: Arial, sans-serif;
`;

const Heading = styled.h2`
  font-size: 24px;
  font-weight: bold;
  color: #333;
  margin-bottom: 20px;
`;

const DropDownWrapper = styled.div`
  position: relative;
  display: inline-block;
  margin-right: 20px;
`;

const DropDownButton = styled.button`
  padding: 10px 15px;
  background-color: #7f8c8d;
  color: white;
  border: none;
  border-radius: 5px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;

  &:hover {
    background-color: #95a5a6;
  }
`;

const DropDownContent = styled.div`
  position: absolute;
  top: 35px;
  left: 0;
  background-color: white;
  border: 1px solid #ccc;
  border-radius: 5px;
  width: 180px;
  z-index: 3;
  display: ${(props) => (props.open ? "block" : "none")};
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
`;

const DropDownItem = styled.div`
  padding: 8px;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f4;
  }
`;

const Input = styled.input`
  padding: 8px 12px;
  font-size: 16px;
  border: 1px solid #ccc;
  border-radius: 4px;
  width: 200px;
  margin-right: 10px;

  &:focus {
    outline: none;
    border-color: #007bff;
  }
`;

const Button = styled.button`
  padding: 8px 16px;
  background-color: #3498db;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 16px;
  margin-left: 10px;

  &:hover {
    background-color: #2980b9;
  }
`;

const SearchWrapper = styled.div`
  display: flex;
  align-items: center;
  margin-bottom: 20px;
`;

const ButtonWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

const AddBook = () => {
  const [criteria, setCriteria] = useState("Title");
  const [inputValue, setInputValue] = useState("");
  const [sort, setSort] = useState("Relevance");
  const [books, setBooks] = useState([]);
  const [searchDropDownOpen, setSearchDropDownOpen] = useState(false);
  const [sortDropDownOpen, setSortDropDownOpen] = useState(false);
  const [page, setPage] = useState(1);
  const [addedBooks, setAddedBooks] = useState({});

  const handleSearch = async () => {
    setBooks([]);
    const result = await fetchQuery(null, criteria, inputValue, sort);
    setBooks(result || []);
  };

  const addtoLib = (book) => {
    if (addedBooks[book.title]) return;

    setAddedBooks((prevState) => ({
      ...prevState,
      [book.title]: true,
    }));

    let myBooks = JSON.parse(localStorage.getItem("books")) || {};
    myBooks[book.title] = book;
    localStorage.setItem("books", JSON.stringify(myBooks));
  };

  const toggleSearchDropDown = () => {
    setSearchDropDownOpen(!searchDropDownOpen);
    setSortDropDownOpen(false);
  };
  const toggleSortDropDown = () => {
    setSortDropDownOpen(!sortDropDownOpen);
    setSearchDropDownOpen(false);
  };

  const handleSearchDropDownItemClick = (newCriteria) => {
    setCriteria(newCriteria);
    setSearchDropDownOpen(false);
  };
  const handleSortDropDownItemClick = (newSort) => {
    setSort(newSort);
    setSortDropDownOpen(false);
  };

  const pageSize = 15;
  const totalPages = Math.ceil(books.length / pageSize);

  return (
    <PageWrapper>
      <Container>
        <Heading>Find Your Books</Heading>
        <SearchWrapper>
          <DropDownWrapper>
            <DropDownButton onClick={toggleSearchDropDown}>
              Search By: {criteria}
            </DropDownButton>
            <DropDownContent open={searchDropDownOpen}>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("Title")}>Title</DropDownItem>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("Author")}>Author</DropDownItem>
              <DropDownItem onClick={() => handleSearchDropDownItemClick("ISBN")}>ISBN</DropDownItem>
            </DropDownContent>
          </DropDownWrapper>

          <DropDownWrapper>
            <DropDownButton onClick={toggleSortDropDown}>Sort By: {sort}</DropDownButton>
            <DropDownContent open={sortDropDownOpen}>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Relevance")}>Relevance</DropDownItem>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Newest")}>Newest</DropDownItem>
              <DropDownItem onClick={() => handleSortDropDownItemClick("Rating")}>Rating</DropDownItem>
            </DropDownContent>
          </DropDownWrapper>

          <Input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder={`Enter ${criteria}`}
          />

          <Button onClick={handleSearch}>Search</Button>
        </SearchWrapper>

        {/* --- GRID --- */}
        <BookGrid>
          {books.length > 0 &&
            books.slice((page - 1) * pageSize, page * pageSize).map((book) => (
              <div key={book.isbn}>
                <BookCard {...book} />
                <ButtonWrapper>
                  <CardButton variant="add" onClick={() => addtoLib(book)}>
                    {addedBooks[book.title] ? "Added! Enjoy Reading!" : "Add to Library"}
                  </CardButton>
                </ButtonWrapper>
              </div>
            ))}
        </BookGrid>

        {books.length > 0 && totalPages > 1 && (
          <div style={{ display: "flex", justifyContent: "center", marginTop: "20px" }}>
            <div>
              {page > 1 && <Button onClick={() => setPage(page - 1)}>{"<"}</Button>}

              {Array.from({ length: totalPages }, (_, index) => (
                <Button
                  key={index}
                  onClick={() => setPage(index + 1)}
                  disabled={page === index + 1}
                  style={{ margin: "5px" }}
                >
                  {index + 1}
                </Button>
              ))}

              {page < totalPages && <Button onClick={() => setPage(page + 1)}>{">"}</Button>}
            </div>
          </div>
        )}
      </Container>
    </PageWrapper>
  );
};

export default AddBook;
